mapper.select:
SELECT * FROM MONITOR_NETWORK_DEVICE D


        AND D.IP_TARGET LIKE concat('%',#{criteria.ip},'%')




                AND D.IS_ONLINE IS NULL


                AND D.IS_ONLINE=#{criteria.isOnline}






                AND D.INSERT_TYPE IS NULL


                AND D.INSERT_TYPE=#{criteria.insertType}




        AND D.MONITOR_ENV = #{criteria.monitorEnv}


        AND D.MONITOR_GROUP = #{criteria.monitorGroup}


        AND D.NETWORK_DEVICE_TYPE LIKE concat('%',#{criteria.networkDeviceType},'%')


        AND D.NETWORK_DEVICE_SUMMARY LIKE concat('%',#{criteria.networkDeviceSummary},'%')


        AND D.IS_ENABLE_MONITOR=#{criteria.isEnableMonitor}


        AND D.IS_ENABLE_ALARM=#{criteria.isEnableAlarm}


ORDER BY D.ID
